import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';

const SUPABASE_URL = "https://zkzontawprihrzpayeam.supabase.co";
const SUPABASE_PUBLISHABLE_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Inprem9udGF3cHJpaHJ6cGF5ZWFtIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzExNjMwMzcsImV4cCI6MjA4NjczOTAzN30.ADUunXjQLnr2HcSdWH3kEAsp8J7qI_XYVmR1d4SbyUg";

