 // @ts-nocheck
// deno-lint-ignore-file no-explicit-any
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, webhook-id, webhook-signature, webhook-timestamp",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    const WEBHOOK_KEY = Deno.env.get("DODO_PAYMENTS_WEBHOOK_KEY") || Deno.env.get("DODO_PAYMENTS_WEBHOOK_SECRET");

    if (!DODO_API_KEY) {
      console.error("DODO_PAYMENTS_API_KEY is not configured");
      await logSystemError({
        function_name: "dodo-webhook",
        error_type: "MISSING_CONFIG",
        severity: "critical",
        error_message: "DODO_PAYMENTS_API_KEY is not configured",
      });
      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
    }
    if (!WEBHOOK_KEY) {
      console.error("DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured");
      await logSystemError({
        function_name: "dodo-webhook",
        error_type: "MISSING_CONFIG",
        severity: "critical",
        error_message: "DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured",
      });
      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
    }

    const rawBody = await req.text();
    const webhookHeaders = {
      "webhook-id": req.headers.get("webhook-id") || "",
      "webhook-signature": req.headers.get("webhook-signature") || "",
      "webhook-timestamp": req.headers.get("webhook-timestamp") || "",
    };

    const dodo = new DodoPayments({
      bearerToken: DODO_API_KEY,
      webhookKey: WEBHOOK_KEY,
    });

    let unwrapped: any;
    try {
      unwrapped = dodo.webhooks.unwrap(rawBody, { headers: webhookHeaders });
    } catch (e) {
      console.error("Invalid webhook signature", e);
      await logSystemError({
        function_name: "dodo-webhook",
        error_type: "WEBHOOK_VALIDATION",
        severity: "critical",
        error_message: errorToMessage(e),
        error_stack: errorToStack(e),
      });
      return new Response("Invalid signature", { status: 401, headers: corsHeaders });
    }

    const eventType: string = unwrapped.type || "unknown";
    const payload: Record<string, unknown> = unwrapped.data || {};
    const webhookId = webhookHeaders["webhook-id"];

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // Idempotency: skip if we've already processed this exact webhook-id
    if (webhookId) {
      const { data: dupList } = await supabase
        .from("subscription_webhooks")
        .select("id")
        .eq("gateway", "dodo")
        .eq("webhook_id", webhookId)
        .limit(1);
      if (dupList && dupList.length > 0) {
        console.log(`Duplicate webhook ${webhookId}, skipping`);
        return new Response("OK", { status: 200, headers: corsHeaders });
      }
    }

    const subscriptionIdForLog = (payload["subscription_id"] as string | undefined) || null;

    // Log the event (unprocessed)
    const logInsert = await supabase
      .from("subscription_webhooks")
      .insert({
        event_type: eventType,
        payload: unwrapped,
        gateway: "dodo",
        processed: false,
        dodo_subscription_id: subscriptionIdForLog,
        webhook_id: webhookId || null,
      })
      .select("id")
      .single();

    const logId: string | null = logInsert.data?.id ?? null;

    async function markProcessed(userId?: string | null) {
      if (!logId) return;
      await supabase
        .from("subscription_webhooks")
        .update({ processed: true, user_id: userId ?? null })
        .eq("id", logId);
    }

    // Prefer correlation via metadata.local_payment_id (set at checkout creation)
    const meta = (payload["metadata"] as Record<string, string> | undefined) || {};
    const localPaymentId = (meta["local_payment_id"] as string | undefined) || null;

    if (eventType === "payment.succeeded" || eventType === "payment_succeeded") {
      const paymentId = (payload["payment_id"] as string | undefined) || null;

      let paymentRow: any = null;
      if (localPaymentId) {
        const { data } = await supabase.from("payments").select("*").eq("id", localPaymentId).single();
        paymentRow = data;
      } else if (paymentId) {
        const { data } = await supabase.from("payments").select("*").eq("dodo_payment_id", paymentId).single();
        paymentRow = data;
      }

      if (paymentRow) {
        // Atomic status transition: only the first delivery wins (idempotent on retries)
        const { data: paidUpdate } = await supabase
          .from("payments")
          .update({
            status: "paid",
            ...(paymentId && !paymentRow.dodo_payment_id ? { dodo_payment_id: paymentId } : {}),
          })
          .eq("id", paymentRow.id)
          .neq("status", "paid")
          .select("id")
          .maybeSingle();
        const newlyPaid = !!paidUpdate;

        if (newlyPaid) {
          // Increment credits atomically to prevent race conditions with verify-dodo-payment
          const creditField = paymentRow.plan_id ? "subscription_credits" : "topup_credits";
          await supabase.rpc("add_credits", {
            _user_id: paymentRow.user_id,
            _credit_field: creditField,
            _amount: paymentRow.credits_purchased,
          });

          // Activate plan if applicable
          if (paymentRow.plan_id) {
            const { data: plan } = await supabase
              .from("plans")
              .select("name, billing_type")
              .eq("id", paymentRow.plan_id)
              .single();

            if (plan) {
              const endsAt = new Date();
              if (plan.billing_type === "yearly") {
                endsAt.setFullYear(endsAt.getFullYear() + 1);
              } else {
                endsAt.setMonth(endsAt.getMonth() + 1);
              }
              await supabase
                .from("profiles")
                .update({
                  plan: plan.name,
                  subscription_ends_at: endsAt.toISOString(),
                  dodo_subscription_id: (payload["subscription_id"] as string | undefined) || null,
                })
                .eq("user_id", paymentRow.user_id);
            }
          }
        }

        await markProcessed(paymentRow.user_id);
      }
    } else if (eventType === "payment.failed" || eventType === "payment_failed") {
      const paymentId = (payload["payment_id"] as string | undefined) || null;
      if (localPaymentId) {
        await supabase
          .from("payments")
          .update({ status: "failed", dodo_payment_id: paymentId })
          .eq("id", localPaymentId);
      } else if (paymentId) {
        await supabase.from("payments").update({ status: "failed" }).eq("dodo_payment_id", paymentId);
      }
      await markProcessed(null);
    } else if (eventType === "subscription.renewed" || eventType === "subscription_renewed") {
      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
      if (subscriptionId) {
        const { data: profile } = await supabase
          .from("profiles")
          .select("user_id, plan, credits, subscription_credits")
          .eq("dodo_subscription_id", subscriptionId)
          .single();

        if (profile) {
          const { data: plan } = await supabase
            .from("plans")
            .select("credits, billing_type")
            .eq("name", profile.plan)
            .single();

          if (plan) {
            const endsAt = new Date();
            if (plan.billing_type === "yearly") {
              endsAt.setFullYear(endsAt.getFullYear() + 1);
            } else {
              endsAt.setMonth(endsAt.getMonth() + 1);
            }
            // Renewal resets subscription_credits to plan amount (monthly allowance, not cumulative).
            // Only add the net delta to total credits so topup_credits and total stay accurate.
            const currentSub = (profile as any).subscription_credits ?? 0;
            const subDelta = plan.credits - currentSub;
            await supabase
              .from("profiles")
              .update({
                subscription_credits: plan.credits,
                credits: (profile.credits ?? 0) + subDelta,
                subscription_ends_at: endsAt.toISOString(),
              })
              .eq("user_id", profile.user_id);
          } else {
            // Plan not found — log critical error but extend subscription to avoid locking user out
            console.error(`Plan "${profile.plan}" not found for renewal. Subscription ${subscriptionId}`);
            await logSystemError({
              function_name: "dodo-webhook",
              error_type: "RENEWAL_PLAN_NOT_FOUND",
              severity: "critical",
              error_message: `Plan "${profile.plan}" not found for subscription renewal ${subscriptionId}`,
              user_id: profile.user_id,
            });
            const fallbackEndsAt = new Date();
            fallbackEndsAt.setMonth(fallbackEndsAt.getMonth() + 1);
            await supabase
              .from("profiles")
              .update({ subscription_ends_at: fallbackEndsAt.toISOString() })
              .eq("user_id", profile.user_id);
          }
        }
      }
      await markProcessed(null);
    } else if (
      eventType === "subscription.cancelled" ||
      eventType === "subscription_cancelled" ||
      eventType === "subscription.on_hold" ||
      eventType === "subscription.failed"
    ) {
      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
      if (subscriptionId) {
        // For on_hold/failed: downgrade immediately; for cancelled, let expiry task handle downgrade.
        if (eventType.includes("on_hold") || eventType.includes("failed")) {
          await supabase
            .from("profiles")
            .update({
              plan: "free",
              dodo_subscription_id: null,
              subscription_ends_at: null,
            })
            .eq("dodo_subscription_id", subscriptionId);
        }
      }
      await markProcessed(null);
    } else if (eventType === "subscription.active" || eventType === "subscription_active") {
      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
      if (subscriptionId && localPaymentId) {
        const { data: payment } = await supabase.from("payments").select("user_id").eq("id", localPaymentId).single();
        if (payment) {
          await supabase.from("profiles").update({ dodo_subscription_id: subscriptionId }).eq("user_id", payment.user_id);
          await markProcessed(payment.user_id);
        }
      }
    }

    return new Response("OK", { status: 200, headers: corsHeaders });
  } catch (err) {
    console.error("dodo-webhook error:", err);
    await logSystemError({
      function_name: "dodo-webhook",
      error_type: "PAYMENT_ERROR",
      severity: "critical",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    return new Response("Internal error", { status: 500, headers: corsHeaders });
  }
});

