import React, { useState, useEffect, useCallback } from "react";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Bell, CheckCircle2, AlertCircle, FileText, Coins, Info, CheckCheck } from "lucide-react";
import { cn } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";

// ─── Types ──────────────────────────────────────────────────────────────────

interface Notification {
  id: string;
  type: "ranking_complete" | "ranking_failed" | "credits_low" | "credits_added" | "system";
  title: string;
  message: string;
  read: boolean;
  created_at: string;
  metadata?: Record<string, any>;
}

const ICON_MAP: Record<Notification["type"], { icon: typeof Bell; color: string; bg: string }> = {
  ranking_complete: { icon: CheckCircle2, color: "text-emerald-600", bg: "bg-emerald-100" },
  ranking_failed: { icon: AlertCircle, color: "text-destructive", bg: "bg-destructive/10" },
  credits_low: { icon: Coins, color: "text-amber-600", bg: "bg-amber-100" },
  credits_added: { icon: Coins, color: "text-blue-600", bg: "bg-blue-100" },
  system: { icon: Info, color: "text-muted-foreground", bg: "bg-muted" },
};

// ─── Component ──────────────────────────────────────────────────────────────

const NotificationBell = () => {
  const { user } = useAuth();
  const [open, setOpen] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [loading, setLoading] = useState(false);

  const unreadCount = notifications.filter((n) => !n.read).length;

  const fetchNotifications = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    try {
      const { data } = await supabase
        .from("notifications")
        .select("id, type, title, message, read, created_at, metadata")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(20);
      if (data) setNotifications(data as Notification[]);
    } catch {
      // Silently fail — notifications are non-critical
    } finally {
      setLoading(false);
    }
  }, [user]);

  // Initial fetch for badge count
  useEffect(() => {
    fetchNotifications();
  }, [fetchNotifications]);

  // Refresh when popover opens
  useEffect(() => {
    if (open) fetchNotifications();
  }, [open]); // eslint-disable-line react-hooks/exhaustive-deps

  // Real-time subscription for new notifications
  useEffect(() => {
    if (!user) return;

    const channel = supabase
      .channel("notifications")
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "notifications",
          filter: `user_id=eq.${user.id}`,
        },
        (payload) => {
          setNotifications((prev) => [payload.new as Notification, ...prev].slice(0, 20));
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user?.id]);

  const markAsRead = async (id: string) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    );
    await supabase.from("notifications").update({ read: true }).eq("id", id);
  };

  const markAllAsRead = async () => {
    if (unreadCount === 0) return;
    const unreadIds = notifications.filter((n) => !n.read).map((n) => n.id);
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
    await supabase.from("notifications").update({ read: true }).in("id", unreadIds);
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          className="relative h-9 w-9 rounded-lg bg-muted flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted/80 transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1"
          aria-label={`Notifications${unreadCount > 0 ? ` (${unreadCount} unread)` : ""}`}
        >
          <Bell className="h-4 w-4" />
          {unreadCount > 0 && (
            <span className="absolute -top-0.5 -right-0.5 flex items-center justify-center min-w-[18px] h-[18px] px-1 rounded-full bg-primary text-primary-foreground text-[10px] font-bold leading-none shadow-sm">
              {unreadCount > 99 ? "99+" : unreadCount}
            </span>
          )}
        </button>
      </PopoverTrigger>

      <PopoverContent align="end" className="w-80 p-0">
        {/* Header */}
        <div className="flex items-center justify-between px-4 pt-3.5 pb-3">
          <h3 className="text-sm font-semibold text-foreground">Notifications</h3>
          {unreadCount > 0 && (
            <button
              onClick={markAllAsRead}
              className="inline-flex items-center gap-1 text-[11px] font-medium text-primary hover:text-primary/80 transition-colors"
            >
              <CheckCheck className="h-3 w-3" />
              Mark all read
            </button>
          )}
        </div>

        <Separator />

        {/* Notification list */}
        <div className="max-h-[360px] overflow-y-auto">
          {loading && notifications.length === 0 ? (
            <div className="px-4 py-8 text-center">
              <div className="h-4 w-4 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto" />
              <p className="text-xs text-muted-foreground mt-2">Loading...</p>
            </div>
          ) : notifications.length === 0 ? (
            <div className="px-4 py-10 text-center">
              <Bell className="h-8 w-8 text-muted-foreground/30 mx-auto mb-2" />
              <p className="text-sm text-muted-foreground">No notifications yet</p>
              <p className="text-xs text-muted-foreground/70 mt-0.5">
                We'll notify you about job rankings and updates.
              </p>
            </div>
          ) : (
            notifications.map((notification) => {
              const style = ICON_MAP[notification.type] ?? ICON_MAP.system;
              const Icon = style.icon;

              return (
                <button
                  key={notification.id}
                  onClick={() => markAsRead(notification.id)}
                  className={cn(
                    "w-full text-left px-4 py-3 flex gap-3 hover:bg-muted/50 transition-colors border-b border-border last:border-0",
                    !notification.read && "bg-primary/[0.03]"
                  )}
                >
                  <div className={cn("h-8 w-8 rounded-lg flex items-center justify-center shrink-0 mt-0.5", style.bg)}>
                    <Icon className={cn("h-4 w-4", style.color)} />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-start justify-between gap-2">
                      <p className={cn("text-sm leading-tight truncate", !notification.read ? "font-semibold text-foreground" : "font-medium text-foreground/80")}>
                        {notification.title}
                      </p>
                      {!notification.read && (
                        <span className="h-2 w-2 rounded-full bg-primary shrink-0 mt-1.5" />
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground line-clamp-2 mt-0.5">
                      {notification.message}
                    </p>
                    <p className="text-[10px] text-muted-foreground/60 mt-1">
                      {formatDistanceToNow(new Date(notification.created_at), { addSuffix: true })}
                    </p>
                  </div>
                </button>
              );
            })
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
};

export default React.memo(NotificationBell);

import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useSeoSettings } from "@/hooks/useSeoSettings";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
  Save, Loader2, Mic, Bot, Plus, Trash2, Eye, EyeOff, Wand2, Copy,
  ExternalLink,
} from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

interface FaqItem {
  q: string;
  a: string;
}

// ─── FAQ Manager sub-component ────────────────────────────────────────────────

interface FaqManagerProps {
  items: FaqItem[];
  onChange: (items: FaqItem[]) => void;
}

const FaqManager = ({ items, onChange }: FaqManagerProps) => {
  const [newQ, setNewQ] = useState("");
  const [newA, setNewA] = useState("");
  const [editIndex, setEditIndex] = useState<number | null>(null);
  const [editQ, setEditQ] = useState("");
  const [editA, setEditA] = useState("");
  const [showPreview, setShowPreview] = useState(false);

  const addItem = () => {
    const q = newQ.trim();
    const a = newA.trim();
    if (!q || !a) { toast.error("Both question and answer are required"); return; }
    onChange([...items, { q, a }]);
    setNewQ("");
    setNewA("");
  };

  const deleteItem = (index: number) => {
    onChange(items.filter((_, i) => i !== index));
  };

  const startEdit = (index: number) => {
    setEditIndex(index);
    setEditQ(items[index].q);
    setEditA(items[index].a);
  };

  const saveEdit = () => {
    if (editIndex === null) return;
    const q = editQ.trim();
    const a = editA.trim();
    if (!q || !a) { toast.error("Both question and answer are required"); return; }
    const updated = items.map((item, i) => (i === editIndex ? { q, a } : item));
    onChange(updated);
    setEditIndex(null);
  };

  const cancelEdit = () => setEditIndex(null);

  const generateFaqJsonLd = () => {
    const schema = {
      "@context": "https://schema.org",
      "@type": "FAQPage",
      mainEntity: items.map((item) => ({
        "@type": "Question",
        name: item.q,
        acceptedAnswer: { "@type": "Answer", text: item.a },
      })),
    };
    return JSON.stringify(schema, null, 2);
  };

  return (
    <div className="space-y-4">
      {/* Existing FAQ list */}
      {items.length > 0 && (
        <div className="space-y-2">
          {items.map((item, index) => (
            <div key={index} className="rounded-md border bg-muted/30 p-3 space-y-2">
              {editIndex === index ? (
                <div className="space-y-2">
                  <div>
                    <Label className="text-xs">Question</Label>
                    <Input value={editQ} onChange={(e) => setEditQ(e.target.value)} className="mt-1" />
                  </div>
                  <div>
                    <Label className="text-xs">Answer</Label>
                    <Textarea value={editA} onChange={(e) => setEditA(e.target.value)} className="mt-1 min-h-[60px]" />
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" onClick={saveEdit}>Save</Button>
                    <Button size="sm" variant="outline" onClick={cancelEdit}>Cancel</Button>
                  </div>
                </div>
              ) : (
                <div className="flex items-start gap-2">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium truncate">{item.q}</p>
                    <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{item.a}</p>
                  </div>
                  <div className="flex gap-1 shrink-0">
                    <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => startEdit(index)}>
                      <Wand2 className="h-3.5 w-3.5" />
                    </Button>
                    <Button variant="ghost" size="icon" className="h-7 w-7 text-destructive hover:text-destructive" onClick={() => deleteItem(index)}>
                      <Trash2 className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Add new FAQ */}
      <div className="rounded-md border border-dashed p-3 space-y-3">
        <p className="text-sm font-medium text-muted-foreground">Add FAQ</p>
        <div>
          <Label className="text-xs">Question</Label>
          <Input
            value={newQ}
            onChange={(e) => setNewQ(e.target.value)}
            placeholder="What is Rankora?"
            className="mt-1"
          />
        </div>
        <div>
          <Label className="text-xs">Answer</Label>
          <Textarea
            value={newA}
            onChange={(e) => setNewA(e.target.value)}
            placeholder="Rankora is an AI-powered resume screening tool..."
            className="mt-1 min-h-[60px]"
          />
        </div>
        <Button size="sm" onClick={addItem} variant="outline">
          <Plus className="h-3.5 w-3.5 mr-1" /> Add FAQ
        </Button>
      </div>

      {/* JSON-LD preview */}
      {items.length > 0 && (
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setShowPreview(!showPreview)}
            className="text-xs text-muted-foreground"
          >
            {showPreview ? <EyeOff className="h-3.5 w-3.5 mr-1" /> : <Eye className="h-3.5 w-3.5 mr-1" />}
            {showPreview ? "Hide" : "Show"} FAQPage JSON-LD Preview
          </Button>
          {showPreview && (
            <pre className="mt-2 text-xs font-mono bg-muted p-3 rounded-md overflow-auto max-h-64 whitespace-pre-wrap">
              {generateFaqJsonLd()}
            </pre>
          )}
        </div>
      )}
    </div>
  );
};

// ─── Main AeoGeoTab ────────────────────────────────────────────────────────────

const LLMS_TXT_ENDPOINT = `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/serve-llms-txt`;

const AeoGeoTab = () => {
  const qc = useQueryClient();
  const { settings, isLoading } = useSeoSettings();
  const [saving, setSaving] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [showLlmsPreview, setShowLlmsPreview] = useState(false);

  const [form, setForm] = useState({
    // AEO
    aeo_enabled: false,
    aeo_speakable_enabled: false,
    aeo_faq_json: [] as FaqItem[],
    // GEO
    geo_enabled: false,
    geo_site_description_for_ai: "",
    geo_author_name: "",
    geo_author_url: "",
    geo_citations_enabled: false,
    geo_llms_txt: "",
  });

  if (settings && !loaded) {
    setForm({
      aeo_enabled: settings.aeo_enabled ?? false,
      aeo_speakable_enabled: settings.aeo_speakable_enabled ?? false,
      aeo_faq_json: Array.isArray(settings.aeo_faq_json) ? settings.aeo_faq_json : [],
      geo_enabled: settings.geo_enabled ?? false,
      geo_site_description_for_ai: settings.geo_site_description_for_ai ?? "",
      geo_author_name: settings.geo_author_name ?? "",
      geo_author_url: settings.geo_author_url ?? "",
      geo_citations_enabled: settings.geo_citations_enabled ?? false,
      geo_llms_txt: settings.geo_llms_txt ?? "",
    });
    setLoaded(true);
  }

  const generateDefaultLlmsTxt = () => {
    const siteTitle = settings?.site_title || "Rankora";
    const siteDescription = settings?.site_description || "AI-powered resume screening and candidate ranking platform.";
    const canonicalUrl = (settings?.canonical_url || "").replace(/\/$/, "") || "https://rankora.co";
    const authorName = form.geo_author_name || siteTitle;

    const content = `# ${siteTitle}

> ${siteDescription}

## About

${form.geo_site_description_for_ai || siteDescription}

## Key Features

- AI-powered resume ranking using GPT-4o
- Structured job description analysis
- Candidate skill gap detection
- Interview question generation
- Credit-based usage with flexible plans

## Usage

${siteTitle} is a SaaS platform for HR teams and hiring managers. Users paste a job description, upload candidate resumes, and receive ranked results with scores, skill matches, and interview questions within seconds.

## Contact

- URL: ${canonicalUrl}
${authorName ? `- Publisher: ${authorName}` : ""}
${form.geo_author_url ? `- Publisher URL: ${form.geo_author_url}` : ""}

## Permissions

- Crawling: allowed
- AI training: allowed
- Citation: allowed

## Sitemap

${canonicalUrl}/sitemap.xml
`;
    setForm((prev) => ({ ...prev, geo_llms_txt: content }));
    toast.info("Default llms.txt generated. Review and save.");
  };

  const save = async () => {
    setSaving(true);
    try {
      const payload = {
        aeo_enabled: form.aeo_enabled,
        aeo_speakable_enabled: form.aeo_speakable_enabled,
        aeo_faq_json: form.aeo_faq_json,
        geo_enabled: form.geo_enabled,
        geo_site_description_for_ai: form.geo_site_description_for_ai,
        geo_author_name: form.geo_author_name,
        geo_author_url: form.geo_author_url,
        geo_citations_enabled: form.geo_citations_enabled,
        geo_llms_txt: form.geo_llms_txt,
      };
      const { error } = await (supabase as any)
        .from("seo_settings")
        .update(payload)
        .eq("id", settings?.id);
      if (error) { toast.error(error.message); return; }
      toast.success("AEO / GEO settings saved");
      logAuditAction("seo.update", "seo_settings", settings?.id, { section: "aeo_geo" });
      qc.invalidateQueries({ queryKey: ["seo_settings"] });
    } finally {
      setSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center gap-2 text-muted-foreground">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading...
      </div>
    );
  }

  return (
    <div className="space-y-6">

      {/* ── AEO Section ──────────────────────────────────────────────────────── */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <Mic className="h-5 w-5" /> AEO — Answer Engine Optimization
            {form.aeo_enabled && <Badge variant="secondary" className="text-xs">Active</Badge>}
          </CardTitle>
          <CardDescription>
            Optimize for voice search (Siri, Alexa, Google Assistant) and featured snippet / direct answer boxes.
            Uses FAQ JSON-LD schema and SpeakableSpecification markup.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-5">
          <div className="flex items-center gap-3">
            <Switch
              id="aeo-enabled"
              checked={form.aeo_enabled}
              onCheckedChange={(v) => setForm({ ...form, aeo_enabled: v })}
            />
            <Label htmlFor="aeo-enabled">Enable AEO Optimizations</Label>
          </div>

          {form.aeo_enabled && (
            <>
              <div className="flex items-center gap-3">
                <Switch
                  id="aeo-speakable"
                  checked={form.aeo_speakable_enabled}
                  onCheckedChange={(v) => setForm({ ...form, aeo_speakable_enabled: v })}
                />
                <div>
                  <Label htmlFor="aeo-speakable">Enable Speakable</Label>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Adds SpeakableSpecification to the WebApplication schema so voice assistants know which content to read aloud.
                  </p>
                </div>
              </div>

              <div>
                <div className="flex items-center justify-between mb-2">
                  <div>
                    <Label>FAQ Structured Data</Label>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Q&amp;A pairs injected as FAQPage JSON-LD. Critical for Google featured snippets and AI answer engines.
                      {form.aeo_faq_json.length > 0 && (
                        <span className="ml-1 text-primary font-medium">{form.aeo_faq_json.length} FAQ{form.aeo_faq_json.length !== 1 ? "s" : ""} added</span>
                      )}
                    </p>
                  </div>
                </div>
                <FaqManager
                  items={form.aeo_faq_json}
                  onChange={(items) => setForm({ ...form, aeo_faq_json: items })}
                />
              </div>
            </>
          )}
        </CardContent>
      </Card>

      {/* ── GEO Section ──────────────────────────────────────────────────────── */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <Bot className="h-5 w-5" /> GEO — Generative Engine Optimization
            {form.geo_enabled && <Badge variant="secondary" className="text-xs">Active</Badge>}
          </CardTitle>
          <CardDescription>
            Optimize for AI-powered search engines: ChatGPT Search, Perplexity, Google SGE, and Bing Copilot.
            Controls citation meta tags, AI-readable description, and the llms.txt file for AI crawlers.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-5">
          <div className="flex items-center gap-3">
            <Switch
              id="geo-enabled"
              checked={form.geo_enabled}
              onCheckedChange={(v) => setForm({ ...form, geo_enabled: v })}
            />
            <Label htmlFor="geo-enabled">Enable GEO Optimizations</Label>
          </div>

          {form.geo_enabled && (
            <>
              {/* AI Description */}
              <div>
                <Label>AI Description</Label>
                <p className="text-xs text-muted-foreground mt-0.5 mb-1">
                  Rich plain-text description written specifically for AI engines. This text explains what the product
                  does, target users, and key features. Injected as{" "}
                  <code className="bg-muted px-1 rounded text-xs">description_ai</code> meta tag.
                </p>
                <Textarea
                  value={form.geo_site_description_for_ai}
                  onChange={(e) => setForm({ ...form, geo_site_description_for_ai: e.target.value })}
                  placeholder="Rankora is an AI-powered resume screening SaaS platform designed for HR teams and hiring managers. Users paste a job description, upload candidate resumes, and receive GPT-4o-scored rankings with skill gap analysis and interview question suggestions within seconds..."
                  className="min-h-[120px]"
                />
              </div>

              {/* Author / Publisher */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <Label>Author / Publisher Name</Label>
                  <Input
                    value={form.geo_author_name}
                    onChange={(e) => setForm({ ...form, geo_author_name: e.target.value })}
                    placeholder="Rankora"
                    className="mt-1"
                  />
                  <p className="text-xs text-muted-foreground mt-1">Used in citation_author meta tag</p>
                </div>
                <div>
                  <Label>Author / Publisher URL</Label>
                  <Input
                    value={form.geo_author_url}
                    onChange={(e) => setForm({ ...form, geo_author_url: e.target.value })}
                    placeholder="https://rankora.co"
                    className="mt-1"
                  />
                  <p className="text-xs text-muted-foreground mt-1">Used in citation_author_institution_url meta tag</p>
                </div>
              </div>

              {/* Citation meta toggle */}
              <div className="flex items-center gap-3">
                <Switch
                  id="geo-citations"
                  checked={form.geo_citations_enabled}
                  onCheckedChange={(v) => setForm({ ...form, geo_citations_enabled: v })}
                />
                <div>
                  <Label htmlFor="geo-citations">Enable Citation Meta Tags</Label>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Adds citation_title and max-snippet:-1 robots directive so AI engines can use full snippets as citations.
                  </p>
                </div>
              </div>

              {/* llms.txt */}
              <div>
                <div className="flex items-center justify-between mb-1">
                  <div>
                    <Label>llms.txt Content</Label>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Emerging standard for AI crawlers. Served at{" "}
                      <code className="bg-muted px-1 rounded text-xs">/llms.txt</code>{" "}
                      via the edge function below. Tells AI engines what your site does and what they may use.
                    </p>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={generateDefaultLlmsTxt}
                    className="shrink-0 ml-4"
                  >
                    <Wand2 className="h-3.5 w-3.5 mr-1" /> Generate Default
                  </Button>
                </div>
                <Textarea
                  value={form.geo_llms_txt}
                  onChange={(e) => setForm({ ...form, geo_llms_txt: e.target.value })}
                  placeholder="# Rankora&#10;&#10;> AI-powered resume screening platform..."
                  className="min-h-[200px] font-mono text-sm mt-1"
                />
              </div>

              {/* llms.txt preview */}
              {form.geo_llms_txt && (
                <div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setShowLlmsPreview(!showLlmsPreview)}
                    className="text-xs text-muted-foreground"
                  >
                    {showLlmsPreview ? <EyeOff className="h-3.5 w-3.5 mr-1" /> : <Eye className="h-3.5 w-3.5 mr-1" />}
                    {showLlmsPreview ? "Hide" : "Show"} llms.txt Preview
                  </Button>
                  {showLlmsPreview && (
                    <pre className="mt-2 text-xs font-mono bg-muted p-3 rounded-md overflow-auto max-h-64 whitespace-pre-wrap">
                      {form.geo_llms_txt}
                    </pre>
                  )}
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* Save */}
      <Button onClick={save} disabled={saving}>
        {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
        Save AEO / GEO Settings
      </Button>

      {/* llms.txt endpoint info */}
      <Card className="border-dashed bg-muted/30">
        <CardHeader className="pb-2 pt-4">
          <CardTitle className="text-sm">llms.txt Dynamic Endpoint</CardTitle>
          <CardDescription className="text-xs">
            The llms.txt content is served live from this Supabase Edge Function URL.
            Configure a rewrite rule on your production domain so{" "}
            <code className="bg-muted px-1 rounded text-xs">/llms.txt</code> proxies to this endpoint,
            or reference it directly.
          </CardDescription>
        </CardHeader>
        <CardContent className="pb-4 space-y-2">
          <div className="flex items-center gap-2 rounded-md bg-muted px-3 py-2">
            <code className="text-xs font-mono flex-1 break-all text-muted-foreground">
              {LLMS_TXT_ENDPOINT}
            </code>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7 shrink-0"
              onClick={() => {
                navigator.clipboard.writeText(LLMS_TXT_ENDPOINT);
                toast.success("URL copied");
              }}
            >
              <Copy className="h-3.5 w-3.5" />
            </Button>
            <Button variant="ghost" size="icon" className="h-7 w-7 shrink-0" asChild>
              <a href={LLMS_TXT_ENDPOINT} target="_blank" rel="noopener noreferrer">
                <ExternalLink className="h-3.5 w-3.5" />
              </a>
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default AeoGeoTab;

