85	  }, [pastJobs, search, showJobList]);
86	
87	  return (
88	    <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
89	      <SidebarHeader className="px-4 py-4">
90	        <button
91	          onClick={onDashboard}
92	          className="flex items-center gap-2 outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-md"
93	        >
94	          <Layers className="h-5 w-5 text-primary" />
95	          <span className="font-semibold text-foreground tracking-tight text-base">Rankora</span>
96	        </button>
97	      </SidebarHeader>
98	      <SidebarSeparator />
99	      <SidebarContent>
100	        {/* Navigation */}
101	        <SidebarGroup>
102	          <SidebarGroupLabel>Navigation</SidebarGroupLabel>
103	          <SidebarGroupContent>
104	            <SidebarMenu>
105	              {isAuthenticated && onDashboard && (
106	                <SidebarMenuItem>
107	                  <SidebarMenuButton isActive={showDashboard && !selectedJobId} onClick={onDashboard}>
108	                    <Home className="h-4 w-4" />
109	                    <span>Dashboard</span>
110	                  </SidebarMenuButton>
111	                </SidebarMenuItem>
112	              )}
113	              {isAuthenticated && onMyJobs && (
114	                <SidebarMenuItem>
115	                  <SidebarMenuButton isActive={showMyJobs || !!selectedJobId} onClick={onMyJobs}>
116	                    <Briefcase className="h-4 w-4" />
117	                    <span>My Jobs</span>
118	                  </SidebarMenuButton>
119	                </SidebarMenuItem>
120	              )}
121	              {isAuthenticated && (
122	                <>
123	                  <SidebarMenuItem>
124	                    <SidebarMenuButton onClick={() => navigate("/billing")}>
125	                      <CreditCard className="h-4 w-4" />
126	                      <span>Billing</span>
127	                    </SidebarMenuButton>
128	                  </SidebarMenuItem>
129	                  <SidebarMenuItem>
130	                    <SidebarMenuButton onClick={() => navigate("/settings")}>
131	                      <Settings className="h-4 w-4" />
132	                      <span>Settings</span>
133	                    </SidebarMenuButton>
134	                  </SidebarMenuItem>
135	                </>
136	              )}
137	            </SidebarMenu>
138	          </SidebarGroupContent>
139	        </SidebarGroup>
140	
141	        {/* Job list — only on My Jobs / Job Detail views */}
142	        {showJobList && isAuthenticated && (
143	          <>
144	            <SidebarSeparator />
145	            <SidebarGroup className="flex-1">
146	              <SidebarGroupLabel>
147	                <span>Jobs</span>
148	                <span className="ml-1.5 inline-flex items-center justify-center h-[18px] min-w-[18px] px-1 rounded-full bg-sidebar-accent text-[10px] font-semibold text-sidebar-foreground/60 tabular-nums">
149	                  {search ? filteredJobs.length : pastJobs.length}
150	                </span>
151	              </SidebarGroupLabel>
152	              <SidebarGroupContent className="space-y-2">
153	                {/* Search + New Job */}
154	                <div className="px-2 space-y-2">
155	                  <Button
156	                    size="sm"
157	                    className="w-full gap-1.5"
158	                    onClick={() => {
159	                      if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; }
160	                      onNewJob();
161	                    }}
162	                  >
163	                    <Plus className="h-3.5 w-3.5" /> New Job
164	                  </Button>
165	                  <div className="relative">
