170	                      onChange={(e) => setSearch(e.target.value)}
171	                      className="pl-8 pr-7"
172	                    />
173	                    {search && (
174	                      <button
175	                        onClick={() => setSearch("")}
176	                        className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
177	                        aria-label="Clear search"
178	                      >
179	                        <X className="h-3.5 w-3.5" />
180	                      </button>
181	                    )}
182	                  </div>
183	                </div>
184	
185	                {/* Job cards */}
186	                {loadingPastJobs ? (
187	                  <div className="space-y-1.5 px-2">
188	                    {[0, 1, 2].map((i) => (
189	                      <div key={i} className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2">
190	                        <Skeleton className="h-4 w-3/4 bg-sidebar-accent" />
191	                        <div className="flex items-center justify-between">
192	                          <Skeleton className="h-3 w-16 bg-sidebar-accent" />
193	                          <Skeleton className="h-3 w-20 bg-sidebar-accent" />
194	                        </div>
195	                      </div>
196	                    ))}
197	                  </div>
198	                ) : filteredJobs.length === 0 ? (
199	                  <p className="text-xs text-muted-foreground px-4 py-4 text-center">
200	                    {search ? "No matching jobs." : "No jobs yet."}
201	                  </p>
202	                ) : (
203	                  <SidebarMenu className="space-y-1 px-2">
204	                    {filteredJobs.map((job) => {
205	                      const isActive = selectedJobId === job.id;
206	                      return (
207	                        <SidebarMenuItem key={job.id}>
208	                          <SidebarMenuButton
209	                            isActive={isActive}
210	                            onClick={() => onSelectJob?.(job.id)}
211	                            className={cn(
212	                              "flex flex-col items-start gap-1.5 h-auto py-2.5 px-3",
213	                              "rounded-lg border transition-colors",
214	                              isActive
215	                                ? "border-l-2 border-l-primary bg-sidebar-accent"
216	                                : "border-transparent hover:bg-sidebar-accent/50"
217	                            )}
218	                          >
219	                            <div className="flex items-center justify-between w-full gap-2">
220	                              <span className="text-sm font-medium leading-snug line-clamp-2 flex-1">
221	                                {getDisplayTitle(job)}
222	                              </span>
223	                              <Badge variant={statusVariant(job.status)} className="text-[10px] px-1.5 py-0 h-4 shrink-0">
224	                                {job.status === "completed" ? "Done" : job.status.charAt(0).toUpperCase() + job.status.slice(1)}
225	                              </Badge>
226	                            </div>
227	                            <div className="flex items-center gap-3 w-full text-[11px] text-muted-foreground">
228	                              <span className="flex items-center gap-1">
229	                                <FileText className="h-2.5 w-2.5" />
230	                                {job.resume_count}
231	                              </span>
232	                              <span className="flex items-center gap-1 ml-auto">
233	                                <Clock className="h-2.5 w-2.5" />
234	                                {format(new Date(job.created_at), "MMM d")}
235	                              </span>
236	                            </div>
