  { icon: ScanLine, title: "AI-Powered Scoring", desc: "GPT-4o scores against your specific JD — contextual matching, not keywords." },
  { icon: Clock, title: "Under 2 Minutes", desc: "Screen resumes instantly. Hours of manual work done in seconds." },
