    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    const contentType = req.headers.get("content-type") ?? "";

    let jobId: string;
    let name: string;
    let email: string;
    let phone: string | null = null;
    let linkedinUrl: string | null = null;
    let resumeFile: File | null = null;

    if (contentType.includes("multipart/form-data")) {
      const form = await req.formData();
      jobId = (form.get("job_id") as string | null)?.trim() ?? "";
      name = (form.get("name") as string | null)?.trim() ?? "";
      email = (form.get("email") as string | null)?.trim() ?? "";
      phone = (form.get("phone") as string | null)?.trim() || null;
      linkedinUrl = (form.get("linkedin_url") as string | null)?.trim() || null;
      const fileEntry = form.get("resume");
      if (fileEntry instanceof File && fileEntry.size > 0) {
        resumeFile = fileEntry;
      }
    } else {
      // Fallback: JSON body (no file upload)
      const body = await req.json();
      jobId = body.job_id?.trim() ?? "";
      name = body.name?.trim() ?? "";
      email = body.email?.trim() ?? "";
      phone = body.phone?.trim() || null;
      linkedinUrl = body.linkedin_url?.trim() || null;
    }

    // ── Validation ────────────────────────────────────────────────────────
    const errors: string[] = [];
    if (!jobId) errors.push("job_id is required");
    if (!name) errors.push("name is required");
    if (!email) errors.push("email is required");
    else if (!isValidEmail(email)) errors.push("email is invalid");

    if (resumeFile) {
      if (resumeFile.size > MAX_RESUME_BYTES) {
        errors.push("Resume file exceeds 10MB limit");
      }
      if (
        !ALLOWED_MIME.includes(resumeFile.type) ||
        !hasAllowedExtension(resumeFile.name)
      ) {
        errors.push("Resume must be a PDF, DOCX, DOC, RTF, or TXT file");
      }
    }

    if (errors.length > 0) {
      return new Response(JSON.stringify({ error: errors.join(". ") }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ── Verify job exists ─────────────────────────────────────────────────
    const { data: job, error: jobError } = await supabase
      .from("jobs")
      .select("id, status")
      .eq("id", jobId)
      .single();

    if (jobError || !job) {
      return new Response(
        JSON.stringify({ error: "Job not found or no longer accepting applications" }),
        {
          status: 404,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // Generate a stable applicant ID for storage path
    const applicantId = crypto.randomUUID();

    // ── Upload resume to storage ───────────────────────────────────────────
    let resumePath: string | null = null;
    let resumeFilename: string | null = null;

    if (resumeFile) {
      const safeFilename = sanitizeFilename(resumeFile.name);
      const storagePath = `applications/${jobId}/${applicantId}/${safeFilename}`;
      const fileBuffer = await resumeFile.arrayBuffer();

      const { error: uploadError } = await supabase.storage
        .from("resumes")
        .upload(storagePath, fileBuffer, {
          contentType: resumeFile.type || "application/octet-stream",
          upsert: false,
        });

      if (uploadError) {
        console.error("Resume upload failed:", uploadError.message);
        // Non-fatal — submit application without resume path
      } else {
        resumePath = storagePath;
        resumeFilename = safeFilename;
      }
    }

    // ── Insert application record ─────────────────────────────────────────
    const { data: application, error: insertError } = await supabase
      .from("applications")
      .insert({
        id: applicantId,
        job_id: jobId,
        name: name.slice(0, 200),
        email: email.toLowerCase().slice(0, 254),
        phone: phone ? phone.slice(0, 50) : null,
        linkedin_url: linkedinUrl ? linkedinUrl.slice(0, 500) : null,
        resume_path: resumePath,
        resume_filename: resumeFilename,
        status: "pending",
      })
      .select("id")
      .single();

    if (insertError || !application) {
      console.error("Application insert failed:", insertError?.message);
      return new Response(
        JSON.stringify({ error: "Failed to submit application. Please try again." }),
        {
          status: 500,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    return new Response(
      JSON.stringify({ success: true, application_id: application.id }),
      {
        status: 201,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "Internal server error";
    console.error("submit-application error:", message);
    return new Response(JSON.stringify({ error: "Internal server error" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

