      }
    }

    // ── Insert application record ─────────────────────────────────────────
    const { data: application, error: insertError } = await supabase
      .from("applications")
      .insert({
        id: applicantId,
        job_id: jobId,
        name: name.slice(0, 200),
        email: email.toLowerCase().slice(0, 254),
        phone: phone ? phone.slice(0, 50) : null,
