import { useState, useRef } from "react";
import { useParams, Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import {
  CheckCircle2,
  Upload,
  FileText,
  X,
  Loader2,
  ExternalLink,
  Briefcase,
} from "lucide-react";

const MAX_FILE_BYTES = 10 * 1024 * 1024; // 10 MB
const ALLOWED_EXTENSIONS = [".pdf", ".docx", ".doc", ".rtf", ".txt"];
const ALLOWED_MIME = [
  "application/pdf",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "application/msword",
  "text/plain",
  "application/rtf",
  "text/rtf",
];

function hasAllowedExtension(filename: string): boolean {
  const lower = filename.toLowerCase();
  return ALLOWED_EXTENSIONS.some((ext) => lower.endsWith(ext));
}

interface JobInfo {
  id: string;
  title: string;
  status: string;
  job_description: string;
}

export default function Apply() {
  const { jobId } = useParams<{ jobId: string }>();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [linkedinUrl, setLinkedinUrl] = useState("");
  const [resumeFile, setResumeFile] = useState<File | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});

  // Fetch minimal job info — no auth required via RPC
  const {
    data: job,
    isLoading: jobLoading,
    error: jobError,
  } = useQuery<JobInfo | null>({
    queryKey: ["apply-job-info", jobId],
    queryFn: async () => {
      if (!jobId) return null;
      const { data, error } = await supabase.rpc("get_job_apply_info", {
        p_job_id: jobId,
      });
      if (error) throw new Error(error.message);
      if (!data || (Array.isArray(data) && data.length === 0)) return null;
      const row = Array.isArray(data) ? data[0] : data;
      return row as JobInfo;
    },
    enabled: !!jobId,
    retry: 1,
    staleTime: 60_000,
  });

  const handleFileSelect = (file: File) => {
    if (file.size > MAX_FILE_BYTES) {
      toast.error("File exceeds 10MB limit");
      return;
    }
    if (!ALLOWED_MIME.includes(file.type) && !hasAllowedExtension(file.name)) {
      toast.error("Please upload a PDF, DOCX, DOC, RTF, or TXT file");
      return;
    }
    setResumeFile(file);
    setFieldErrors((prev) => ({ ...prev, resume: "" }));
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files[0];
    if (file) handleFileSelect(file);
  };

  const validate = (): boolean => {
    const errors: Record<string, string> = {};
    if (!name.trim()) errors.name = "Name is required";
    if (!email.trim()) errors.email = "Email is required";
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))
      errors.email = "Enter a valid email address";
    setFieldErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;
    if (!jobId) {
      toast.error("Invalid application link");
      return;
    }

    setSubmitting(true);
    try {
      const form = new FormData();
      form.append("job_id", jobId);
      form.append("name", name.trim());
      form.append("email", email.trim().toLowerCase());
      if (phone.trim()) form.append("phone", phone.trim());
      if (linkedinUrl.trim()) form.append("linkedin_url", linkedinUrl.trim());
      if (resumeFile) form.append("resume", resumeFile);

      const { data: sessionData } = await supabase.auth.getSession();
      const headers: Record<string, string> = {
        // Supabase project URL and anon key from env — required even for anon calls
        apikey: import.meta.env.VITE_SUPABASE_ANON_KEY as string,
      };
      if (sessionData.session?.access_token) {
        headers["Authorization"] = `Bearer ${sessionData.session.access_token}`;
      } else {
        headers["Authorization"] = `Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY as string}`;
      }

      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
      const res = await fetch(
        `${supabaseUrl}/functions/v1/submit-application`,
        {
          method: "POST",
          headers,
          body: form,
        }
      );

      const json = await res.json();
      if (!res.ok) {
        throw new Error(json.error || "Failed to submit application");
      }

      setSubmitted(true);
    } catch (err: unknown) {
      const message =
        err instanceof Error ? err.message : "Submission failed. Please try again.";
      toast.error(message);
    } finally {
      setSubmitting(false);
    }
  };

  // ── Success screen ──────────────────────────────────────────────────────
  if (submitted) {
    return (
      <div className="min-h-screen bg-background flex flex-col">
        <ApplyHeader />
        <main className="flex-1 flex items-center justify-center px-4 py-16">
          <div className="w-full max-w-md text-center space-y-6">
            <div className="flex justify-center">
              <div className="w-16 h-16 rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center">
                <CheckCircle2 className="h-8 w-8 text-emerald-600 dark:text-emerald-400" />
              </div>
            </div>
            <div className="space-y-2">
              <h1 className="text-2xl font-semibold tracking-tight">
                Application Submitted Successfully!
              </h1>
              <p className="text-sm text-muted-foreground leading-relaxed">
                Thank you! We will review your information and get in touch shortly.
              </p>
            </div>
            <Link
              to="/"
              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
            >
              Back to Jobs
            </Link>
          </div>
        </main>
        <ApplyFooter />
      </div>
    );
  }

  // ── Job not found ───────────────────────────────────────────────────────
  // Note: status === "failed" means the ranking pipeline failed, NOT that the
  // job is closed for applications. We don't block applications on failed jobs.
  if (!jobLoading && (jobError || !job)) {
    return (
      <div className="min-h-screen bg-background flex flex-col">
        <ApplyHeader />
        <main className="flex-1 flex items-center justify-center px-4 py-16">
          <div className="w-full max-w-md text-center space-y-4">
            <div className="flex justify-center">
              <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center">
                <Briefcase className="h-7 w-7 text-muted-foreground" />
              </div>
            </div>
            <h1 className="text-xl font-semibold">Job not found</h1>
            <p className="text-sm text-muted-foreground">
              This application link may have expired or the job no longer exists.
            </p>
            <Link
              to="/"
              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
            >
              Back to Jobs
            </Link>
          </div>
        </main>
        <ApplyFooter />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <ApplyHeader />

      <main className="flex-1 flex items-start justify-center px-4 py-10">
        <div className="w-full max-w-lg">
          {/* Job title */}
          <div className="mb-8 space-y-1">
            {jobLoading ? (
              <>
                <Skeleton className="h-7 w-64" />
                <Skeleton className="h-4 w-40 mt-2" />
              </>
            ) : (
              <>
                <h1 className="text-2xl font-semibold tracking-tight leading-tight">
                  {job?.title ?? "Apply for this position"}
                </h1>
                {job?.job_description && (
                  <div className="mt-4 rounded-lg border border-border bg-muted/30 p-4 max-h-60 overflow-y-auto">
                    <h2 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">
                      Job Description
                    </h2>
                    <p className="text-sm text-foreground whitespace-pre-line leading-relaxed">
                      {job.job_description}
                    </p>
                  </div>
                )}
                <p className="text-sm text-muted-foreground mt-3">
                  Fill in your details below to apply.
                </p>
              </>
            )}
          </div>

          <form onSubmit={handleSubmit} noValidate className="space-y-5">
            {/* Name */}
            <div className="space-y-1.5">
              <Label htmlFor="apply-name">
                Full Name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="apply-name"
                type="text"
                placeholder="Jane Smith"
                value={name}
                onChange={(e) => {
                  setName(e.target.value);
                  if (fieldErrors.name)
                    setFieldErrors((prev) => ({ ...prev, name: "" }));
                }}
                autoComplete="name"
                aria-invalid={!!fieldErrors.name}
                aria-describedby={fieldErrors.name ? "name-error" : undefined}
                disabled={submitting}
              />
              {fieldErrors.name && (
                <p id="name-error" className="text-xs text-destructive">
                  {fieldErrors.name}
                </p>
              )}
            </div>

            {/* Email */}
            <div className="space-y-1.5">
              <Label htmlFor="apply-email">
                Email Address <span className="text-destructive">*</span>
              </Label>
              <Input
                id="apply-email"
                type="email"
                placeholder="jane@example.com"
                value={email}
                onChange={(e) => {
                  setEmail(e.target.value);
                  if (fieldErrors.email)
                    setFieldErrors((prev) => ({ ...prev, email: "" }));
                }}
                autoComplete="email"
                aria-invalid={!!fieldErrors.email}
                aria-describedby={fieldErrors.email ? "email-error" : undefined}
                disabled={submitting}
              />
              {fieldErrors.email && (
                <p id="email-error" className="text-xs text-destructive">
                  {fieldErrors.email}
                </p>
              )}
            </div>

            {/* Phone */}
            <div className="space-y-1.5">
              <Label htmlFor="apply-phone">Phone Number</Label>
              <Input
                id="apply-phone"
                type="tel"
                placeholder="+1 555 000 0000"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                autoComplete="tel"
                disabled={submitting}
              />
            </div>

            {/* Resume Upload */}
            <div className="space-y-1.5">
              <Label>Resume / CV <span className="text-xs font-normal text-muted-foreground">(optional)</span></Label>
              {resumeFile ? (
                <div className="flex items-center gap-3 rounded-lg border border-border bg-secondary/40 px-4 py-3">
                  <FileText className="h-5 w-5 text-primary shrink-0" />
                  <span className="flex-1 text-sm truncate">{resumeFile.name}</span>
                  <button
                    type="button"
                    onClick={() => {
                      setResumeFile(null);
                      if (fileInputRef.current) fileInputRef.current.value = "";
                    }}
                    className="text-muted-foreground hover:text-destructive transition-colors"
                    aria-label="Remove resume"
                    disabled={submitting}
                  >
                    <X className="h-4 w-4" />
                  </button>
                </div>
              ) : (
                <div
                  role="button"
                  tabIndex={0}
                  aria-label="Upload resume — PDF, DOCX, DOC, RTF, or TXT, max 10MB"
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ")
                      fileInputRef.current?.click();
                  }}
                  className={`border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-all duration-200 flex flex-col items-center gap-2 focus:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
                    dragOver
                      ? "border-primary bg-primary/5 scale-[1.01]"
                      : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
                  }`}
                  onDragOver={(e) => {
                    e.preventDefault();
                    setDragOver(true);
                  }}
                  onDragLeave={() => setDragOver(false)}
                  onDrop={handleDrop}
                  onClick={() => fileInputRef.current?.click()}
                >
                  <div className="w-10 h-10 rounded-lg bg-muted flex items-center justify-center">
                    <Upload className="h-5 w-5 text-primary" />
                  </div>
                  <p className="text-sm font-medium text-foreground">
                    Drop your resume here or{" "}
                    <span className="text-primary">click to browse</span>
                  </p>
                  <p className="text-xs text-muted-foreground">
                    PDF, DOCX, DOC, RTF, TXT · Max 10MB
                  </p>
                  <input
                    ref={fileInputRef}
                    id="resume-input"
                    type="file"
                    className="hidden"
                    accept=".pdf,.docx,.doc,.rtf,.txt"
                    onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (file) handleFileSelect(file);
                    }}
                    disabled={submitting}
                  />
                </div>
              )}
            </div>

            {/* LinkedIn URL */}
            <div className="space-y-1.5">
              <Label htmlFor="apply-linkedin" className="flex items-center gap-1.5">
                LinkedIn Profile
                <span className="text-xs font-normal text-muted-foreground">
                  (optional)
                </span>
              </Label>
              <div className="relative">
                <Input
                  id="apply-linkedin"
                  type="url"
                  placeholder="https://linkedin.com/in/jane-smith"
                  value={linkedinUrl}
                  onChange={(e) => setLinkedinUrl(e.target.value)}
                  className="pr-9"
                  disabled={submitting}
                />
                <ExternalLink className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
              </div>
            </div>

            {/* Submit */}
            <Button
              type="submit"
              className="w-full gap-2"
              size="lg"
              disabled={submitting}
            >
              {submitting ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Submitting…
                </>
              ) : (
                "Submit Application"
              )}
            </Button>
          </form>
        </div>
      </main>

      <ApplyFooter />
    </div>
  );
}

function ApplyHeader() {
  return (
    <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
      <div className="max-w-2xl mx-auto px-4 py-4 flex items-center gap-2">
        <Link
          to="/"
          className="flex items-center gap-2 text-sm font-semibold text-foreground hover:text-primary transition-colors"
        >
          <div className="w-6 h-6 rounded bg-primary flex items-center justify-center">
            <span className="text-[11px] font-bold text-primary-foreground">R</span>
          </div>
          Rankora
        </Link>
      </div>
    </header>
  );
}

function ApplyFooter() {
  return (
    <footer className="py-6 text-center">
      <p className="text-xs text-muted-foreground">
        Powered by{" "}
        <Link to="/" className="text-primary font-medium hover:text-primary/80 transition-colors">
          Rankora
        </Link>
      </p>
    </footer>
  );
}

